import React from "react";
import { Modal, Button } from "react-bootstrap";
import ErrorOutlineIcon from "@mui/icons-material/ErrorOutline";
import CancelOutlinedIcon from "@mui/icons-material/CancelOutlined";

function AepsErrorModal({ show, onHide, errorData }) {
  if (!errorData) return null;

  const title = errorData?.title || "Transaction Failed";
  const message =
    errorData?.message ||
    errorData?.error_message ||
    "Transaction could not be completed. Please check details and try again.";
  const bankName = errorData?.bankName || errorData?.data?.bank_name;
  const amount = errorData?.amount || errorData?.data?.amount;
  const rrn = errorData?.rrn || errorData?.data?.bank_rrn || errorData?.data?.txn_id;
  const lastAadhaar = errorData?.lastAadhaar || errorData?.data?.last_adhaar;

  return (
    <Modal
      show={show}
      onHide={onHide}
      centered
      backdrop="static"
      keyboard={false}
      style={{ zIndex: 1060 }}
    >
      <Modal.Header
        closeButton
        style={{
          backgroundColor: "#fff5f5",
          borderBottom: "1px solid #fed7d7",
          padding: "16px 20px",
        }}
      >
        <Modal.Title
          style={{
            fontSize: "18px",
            fontWeight: 700,
            color: "#c53030",
            display: "flex",
            alignItems: "center",
            gap: "8px",
          }}
        >
          <CancelOutlinedIcon style={{ fontSize: "24px", color: "#e53e3e" }} />
          {title}
        </Modal.Title>
      </Modal.Header>

      <Modal.Body style={{ padding: "24px 20px", backgroundColor: "#ffffff" }}>
        {/* Error icon + main message banner */}
        <div
          style={{
            backgroundColor: "#fff5f5",
            border: "1.5px solid #feb2b2",
            borderRadius: "12px",
            padding: "16px",
            marginBottom: "20px",
            textAlign: "center",
          }}
        >
          <div
            style={{
              width: "52px",
              height: "52px",
              borderRadius: "50%",
              backgroundColor: "#fed7d7",
              color: "#c53030",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              margin: "0 auto 12px auto",
            }}
          >
            <ErrorOutlineIcon style={{ fontSize: "32px" }} />
          </div>

          <div
            style={{
              fontSize: "15px",
              fontWeight: 700,
              color: "#9b2c2c",
              lineHeight: 1.4,
              wordBreak: "break-word",
            }}
          >
            {message}
          </div>
        </div>

        {/* Transaction details if available */}
        {(bankName || amount || rrn || lastAadhaar) && (
          <div
            style={{
              backgroundColor: "#f7fafc",
              borderRadius: "10px",
              padding: "14px 16px",
              border: "1px solid #edf2f7",
            }}
          >
            {bankName && (
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  padding: "4px 0",
                  fontSize: "13.5px",
                }}
              >
                <span style={{ color: "#718096", fontWeight: 600 }}>Bank:</span>
                <span style={{ color: "#2d3748", fontWeight: 700 }}>{bankName}</span>
              </div>
            )}

            {amount !== undefined && amount !== null && amount !== "" && (
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  padding: "4px 0",
                  fontSize: "13.5px",
                }}
              >
                <span style={{ color: "#718096", fontWeight: 600 }}>Amount:</span>
                <span style={{ color: "#2d3748", fontWeight: 700 }}>₹{amount}</span>
              </div>
            )}

            {lastAadhaar && (
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  padding: "4px 0",
                  fontSize: "13.5px",
                }}
              >
                <span style={{ color: "#718096", fontWeight: 600 }}>Aadhaar:</span>
                <span style={{ color: "#2d3748", fontWeight: 700 }}>
                  XXXX-XXXX-{lastAadhaar}
                </span>
              </div>
            )}

            {rrn && (
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  padding: "4px 0",
                  fontSize: "13.5px",
                }}
              >
                <span style={{ color: "#718096", fontWeight: 600 }}>RRN / Txn ID:</span>
                <span
                  style={{
                    color: "#2d3748",
                    fontWeight: 700,
                    fontSize: "12px",
                    maxWidth: "60%",
                    wordBreak: "break-all",
                    textAlign: "right",
                  }}
                >
                  {rrn}
                </span>
              </div>
            )}
          </div>
        )}

        <div style={{ marginTop: "16px", textAlign: "center", fontSize: "12px", color: "#a0aec0" }}>
          This failure report will stay visible until you click OK.
        </div>
      </Modal.Body>

      <Modal.Footer style={{ borderTop: "1px solid #edf2f7", padding: "12px 20px" }}>
        <Button
          variant="danger"
          onClick={onHide}
          style={{
            width: "100%",
            fontWeight: 700,
            padding: "10px 0",
            fontSize: "15px",
            borderRadius: "8px",
            backgroundColor: "#e53e3e",
            borderColor: "#e53e3e",
          }}
        >
          OK / Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
}

export default AepsErrorModal;
